import { useEffect, useMemo, useState } from "react";
import { buildFlower } from "../flower/engine";
import type { FlowerRecipe } from "../flower/recipe";
import { drawingToSvg, type Framing } from "../flower/render";

/**
 * Live SVG preview of a flower. The SVG is generated by our own renderer from
 * the recipe; all text inside it is XML-escaped, so it is safe to inline.
 */
export function FlowerPreview({
  recipe,
  framing = "window",
  background = true,
  className = "flower-svg",
  label,
  growKey,
}: {
  recipe: FlowerRecipe;
  framing?: Framing;
  background?: boolean;
  className?: string;
  label?: string;
  /** Change this number to replay the growing animation (like the turtle drawing it). */
  growKey?: number;
}) {
  const drawing = useMemo(() => buildFlower(recipe), [recipe]);
  const total = drawing.primitives.length;
  // null = show everything; a number = part-way through the growing animation
  const [shown, setShown] = useState<number | null>(null);

  useEffect(() => {
    if (!growKey) return;
    if (window.matchMedia?.("(prefers-reduced-motion: reduce)").matches) return;
    let frame = 0;
    const start = performance.now();
    const duration = 1800;
    const step = (now: number) => {
      const t = Math.min(1, (now - start) / duration);
      if (t < 1) {
        setShown(Math.max(1, Math.round(total * t)));
        frame = requestAnimationFrame(step);
      } else {
        setShown(null);
      }
    };
    setShown(1);
    frame = requestAnimationFrame(step);
    return () => {
      cancelAnimationFrame(frame);
      setShown(null);
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [growKey]);

  const svg = useMemo(
    () =>
      drawingToSvg(
        { ...drawing, primitives: shown === null ? drawing.primitives : drawing.primitives.slice(0, shown) },
        { framing, background, title: label ?? `A flower grown from “${recipe.word}”` },
      ),
    [drawing, shown, total, framing, background, label, recipe.word],
  );
  return <div className={className} role="img" aria-label={label ?? `Flower made of the word ${recipe.word}`} dangerouslySetInnerHTML={{ __html: svg }} />;
}
